ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  items: payload map ((r) -> {
    queueId: r.queue_id, invoiceId: r.invoice_id, failureType: r.failure_type, errorCode: r.error_code,
    errorMessage: r.error_message, attemptCount: r.attempt_count, maxAttempts: r.max_attempts,
    status: r.status, nextAttemptAt: r.next_attempt_at, createdAt: r.created_at
  })
}
